		"config_auto_str_28":"<div class='bt-form pd20'>\t\t\t\t<div class='line'>\t\t\t\t\t<span class='tname'>Nome utente</span>\ t\t\t\t\t<div class='info-r'><input class='bt-input-text' type='text' name='username' value='' style='width:85%' autocomplete='off'/></div>\t\t\t\t</div>\t\t\t\t<div class='line'>\t\t\t\t\t<span class='tname'>Password</span>\ t\t\t\t\t<div class='info-r'><input class='bt-input-text' type='password' name='password' value='' style='width:85%' autocomplete='off'/></div>\t\t\t\t</div>\t\t\t</div>",
