		"config_auto_str_39":"Attenzione: disattivare l'accesso sicuro equivale a esporre direttamente l'indirizzo del tuo pannello di amministrazione alla rete esterna, il che è estremamente pericoloso. Vuoi davvero apportare questa modifica?",
