		"config_auto_str_134":"<li>Incolla il contenuto dei tuoi file *.key e *.pem, quindi salva. </li>\t\t\t\t\t\t\t\t\t<li>Se il browser segnala che la catena di certificati è incompleta, verificare che il certificato in formato PEM sia stato assemblato correttamente</li><li>Certificato in formato PEM = certificato del dominio.crt + certificato radice (root_bundle).crt</li>",
